<?php
$fmt = static function ($n) {
    $n = (int) $n;
    return $n >= 1073741824 ? number_format($n / 1073741824, 2, ',', '.') . ' GB'
        : ($n >= 1048576 ? number_format($n / 1048576, 1, ',', '.') . ' MB'
        : number_format($n / 1024, 1, ',', '.') . ' KB');
};
$folders = $isAdmin ? $wilayahList : array_values(array_filter($wilayahList, static fn($w) => (int)$w['id'] === (int)$user['sub_wilayah_id']));
?>
