<div class="overlay" id="detailOverlay" hidden role="dialog" aria-modal="true" aria-labelledby="detailTitle"><div class="modal"><div class="modalhead"><div><h2 id="detailTitle">Detail Dokumen</h2><div class="muted" id="detailSub"></div></div><button type="button" class="action" id="closeTop" aria-label="Tutup detail">Tutup &times;</button></div><div class="modalbody"><div class="details"><div class="detail"><small>Sub Wilayah</small><strong id="dRegion"></strong></div><div class="detail"><small>Tahun / Masa Sidang</small><strong id="dPeriod"></strong></div><div class="detail"><small>Ukuran Dokumen</small><strong id="dSize"></strong></div><div class="detail"><small>Pengunggah</small><strong id="dUploader"></strong></div><div class="detail"><small>Kategori</small><strong id="dCategory"></strong></div><div class="detail"><small>Tanggal Unggah</small><strong id="dDate"></strong></div></div><div class="preview" id="previewArea"></div></div><div class="modalfoot"><a id="downloadLink" class="btn" href="#">Unduh Dokumen</a><button type="button" class="btn light" id="closeBottom">Tutup</button></div></div></div>
<script>
(function(){
const overlay=document.getElementById('detailOverlay'),area=document.getElementById('previewArea');let previousFocus=null;
function close(){overlay.hidden=true;area.replaceChildren();document.body.style.overflow='';if(previousFocus)previousFocus.focus();}
function open(d){previousFocus=document.activeElement;document.getElementById('detailTitle').textContent=d.name;document.getElementById('detailSub').textContent='Informasi dan pratinjau dokumen';const ids={dRegion:'region',dPeriod:'period',dSize:'size',dUploader:'uploader',dCategory:'category',dDate:'date'};Object.entries(ids).forEach(([id,key])=>document.getElementById(id).textContent=d[key]||'-');document.getElementById('downloadLink').href=d.download;area.replaceChildren();if(d.preview){const frame=document.createElement('iframe');frame.title='Preview '+d.name;frame.src=d.preview;frame.setAttribute('loading','lazy');area.appendChild(frame);}else{const message=document.createElement('div');message.className='previewmsg';message.textContent='Preview tersedia untuk PDF dan gambar. Untuk format dokumen ini, gunakan tombol Unduh Dokumen.';area.appendChild(message);}overlay.hidden=false;document.body.style.overflow='hidden';document.getElementById('closeTop').focus();}
document.querySelectorAll('[data-document]').forEach(btn=>btn.addEventListener('click',()=>{try{open(JSON.parse(btn.dataset.document));}catch(e){alert('Detail dokumen tidak dapat dibuka.');}}));document.getElementById('closeTop').addEventListener('click',close);document.getElementById('closeBottom').addEventListener('click',close);overlay.addEventListener('click',e=>{if(e.target===overlay)close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!overlay.hidden)close();});
})();
</script></body></html>
